const ic=(name,cls='icon')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.heart}"/></svg>`;
const arrow=()=>ic('arrow');
const brand=()=>`<a href="index.html" class="brand" aria-label="Covenant Matrimony home"><img src="assets/crest.svg" alt=""><div class="brand-name">COVENANT<span>Matrimony</span></div></a>`;
const page=document.body.dataset.page;
const config=window.COVENANT_CONFIG||{backend:'mock',api:'/api.php'};
let csrf=null;
let state, user=null, view=location.hash.slice(1)||'overview',loginRole='member',interestTab='received',lastFocus=null,modalKind='',wizardStep=0,wizardData={};
const storageKey='covenant-showcase-v1';
function loadState(){try{return JSON.parse(localStorage.getItem(storageKey))||seed();}catch{return seed();}}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(state));}catch{}}
async function api(action,payload={},method='POST'){
 const res=await fetch(config.api,{method,credentials:'same-origin',headers:method==='POST'?{'Content-Type':'application/json',...(csrf?{'X-CSRF-Token':csrf}:{})}:{},body:method==='POST'?JSON.stringify({action,payload}):undefined});
 const data=await res.json();if(data.csrf)csrf=data.csrf;if(!res.ok)throw Error(data.error||'Could not complete this action.');return data;
}
async function mutate(action,payload={}){if(config.backend==='php'){const r=await api(action,payload);state=r.state;}else{const next=structuredClone(state);state=apply(next,user,action,payload);persist();}return state;}
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),3800);}
const badge=(status)=>`<span class="badge ${['Awaiting consent','Under review','Pending','Proposed','Awaiting assignment'].includes(status)?'warn':['Changes requested','Suspended','Declined','Change requested'].includes(status)?'danger':['Draft','Withdrawn'].includes(status)?'neutral':''}"><span class="dot"></span>${esc(status)}</span>`;
const avatar=(p,cls='')=>p&&p.photoVisible!==false&&p.photo!==false?`<div class="avatar-photo quad-${p.portrait||0} ${cls}" role="img" aria-label="Illustrative portrait of ${esc(p.name)}"></div>`:`<div class="initials ${cls}">${esc(p?.name?.split(' ').map(n=>n[0]).join('')||'CM')}</div>`;
const profileById=id=>state.profiles.find(p=>p.id===id);
function header(){return `<header class="header wrap">${brand()}<nav class="public-nav" aria-label="Main navigation">${[['home','Home','index.html'],['about','About us','about.html'],['specialties','Our specialties','specialties.html']].map(([p,n,h])=>`<a href="${h}" ${page===p?'aria-current="page"':''}>${n}</a>`).join('')}</nav><div class="nav-actions"><a href="login.html">Sign in</a><button class="btn small" data-action="register">Create a profile ${arrow()}</button><button class="menu-button" data-action="menu" aria-label="Open navigation" aria-expanded="false">${ic('menu')}</button></div></header>`;}
function footer(){return `<footer class="footer wrap"><div class="footer-top">${brand()}<nav aria-label="Footer"><a href="about.html">Our approach</a><a href="specialties.html">Our specialties</a><a href="login.html">Sign in</a><button class="text-link" style="padding:0;border:0;font-size:15px" data-action="enquiry">Contact us</button></nav></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Covenant Matrimony. A thoughtful beginning.</span><div class="links"><button data-action="privacy-policy">Privacy</button><button data-action="terms">Terms</button><span>Showcase · Illustrative imagery</span></div></div></footer>`;}
function closing(title='Begin with a conversation<br>about your future.',copy='Create your profile, or ask us about registration through a church or local branch.'){return `<section class="closing"><span class="ornament" aria-hidden="true">&</span><div class="eyebrow">Your next chapter</div><h2>${title}</h2><p>${copy}</p><div class="actions"><button class="btn" data-action="register">Create your profile ${arrow()}</button><button class="text-link" data-action="enquiry">Speak to our team ${arrow()}</button></div></section>`;}
const journeys=[['Getting to know you','Begin online, through a church or at a branch. Share what matters to you and your family.',0],['Your profile and review','Complete your details and required evidence. Our team reviews your submission before it becomes discoverable.',1],['Profiles to consider','Explore eligible profiles with permitted photos, guided by your faith, location and partner preferences.',3],['Mutual interest','Express interest and receive a response. Both people choose whether to take the next step.',3],['A guided family introduction','An assigned pastor or representative seeks permission and helps connect the two families.',0],['Meeting and feedback','Arrange a meeting, share your thoughts privately and discuss whether you would like to continue.',0],['Premarital counselling','Prepare for married life through the counselling process agreed with Covenant and your families.',2],['Moving towards marriage','Celebrate the next milestone with your coordinator as you move towards marriage.',4]];
function home(){return `${header()}<main id="main"><section class="hero wrap"><div class="hero-copy"><div class="eyebrow">Christian matrimony, thoughtfully guided</div><h1>Someone who<br>shares your faith.<br><em>And your life.</em></h1><p class="lead">Your faith, family and hopes for the future deserve a thoughtful introduction. Begin a journey with room for everything that matters to you.</p><div class="actions"><button class="btn" data-action="register">Create your profile ${arrow()}</button><a class="text-link" href="about.html">Discover our approach ${arrow()}</a></div><div class="privacy-line">${ic('shield')}<span>Your details stay private. Family introductions happen with your permission.</span></div><div class="hero-index">FAITH. FAMILY. A FUTURE TOGETHER.</div></div><div class="hero-photo"><img src="assets/hero.webp" alt="Illustrative Indian Christian bride and groom in a church garden" fetchpriority="high"><div class="hero-stamp">A thoughtful<br>beginning<small>Rooted in faith</small></div><div class="photo-caption">${ic('heart')}Shared faith. A world of possibility.</div></div></section><div class="principles wrap reveal">${[['church','Faith that is understood','Find room for the beliefs and practices that matter in your everyday life.'],['people','Families that feel included','Bring your family into the process while keeping your choices clear.'],['leaf','Guidance when it matters','Know who to speak to when interest becomes a conversation.']].map(([i,h,p])=>`<div class="principle">${ic(i)}<div><h3>${h}</h3><p>${p}</p></div></div>`).join('')}</div><section class="entry-section"><div class="wrap reveal"><div class="section-head"><div><div class="eyebrow">Your beginning, your way</div><h2>Three ways to take<br>the first step.</h2></div><p>One connected journey. Choose the way you feel most comfortable beginning.</p></div><div class="entry-grid">${[['01','profile','Join online','Create your profile at your own pace and follow every step from your dashboard.','Create a profile','register'],['02','church','Through your church','Begin with the assistance of an authorised representative from a partner church.','Ask about church registration','church-enquiry'],['03','branch','Through a local branch','Get help completing your profile from an approved Covenant branch team.','Ask about branch assistance','branch-enquiry']].map(([n,i,h,p,c,a])=>`<article class="entry"><div class="number"><span>${n} / A WAY TO BEGIN</span>${ic(i)}</div><h3>${h}</h3><p>${p}</p><button class="text-link" data-action="${a}">${c} ${arrow()}</button></article>`).join('')}</div></div></section><section class="journey-section wrap reveal" id="journey"><div class="section-head"><div><div class="eyebrow">Your journey with Covenant</div><h2>From the first introduction<br>to the next chapter.</h2></div><p>Understand the steps ahead, with people to guide you through each conversation.</p></div>${carouselToolbar('Eight stages. Open one to see how it unfolds.','journey-track','journey-step')}<div class="journey-panels journey-accordion" id="journey-track" role="group" aria-label="Eight stages in your Covenant journey">${journeys.map(([title,copy,q],i)=>`<button type="button" class="journey-panel" data-journey="${i}" aria-expanded="${i===0}" aria-controls="journey-detail-${i}" aria-labelledby="journey-label-${i}" ${i===0?'aria-describedby="journey-description-0"':''}><img class="journey-image" src="assets/${q===4?'hero':'stories-'+q}.webp" alt="" loading="lazy"><span class="journey-num" aria-hidden="true">0${i+1}</span><span class="journey-rail" id="journey-label-${i}">${title}</span><span class="journey-detail" id="journey-detail-${i}" aria-hidden="${i!==0}"><span class="journey-detail-number" aria-hidden="true">0${i+1}</span><span class="journey-title" aria-hidden="true">${title}</span><span class="journey-description" id="journey-description-${i}">${copy}</span></span></button>`).join('')}</div><div class="journey-note"><span>Hover, tap or use the arrows to open each stage.</span><span>A guided process. Each next step is your choice.</span></div></section><section class="reach-section" id="reach"><div class="wrap reach-grid reveal"><div><div class="eyebrow light">Connections across India</div><h2>Shared faith.<br>Familiar roots.<br><em>New possibilities.</em></h2><p>Tell us where you would like to begin. Share your location, language and hopes for the life ahead.</p><div class="state-options">${states.map((s,i)=>`<button class="state-chip" data-state="${s}" aria-pressed="${i===0}">${s}</button>`).join('')}</div><div class="regional-card" id="regional-card">${regionContent('Karnataka')}</div></div><div class="map-holder" id="india-map"><div class="map-loading">Five states. A shared beginning.</div></div></div></section><section class="faq-section wrap reveal"><div><div class="eyebrow">Clarity before you begin</div><h2>A few things<br>to know.</h2></div><div>${[['Can I see a photograph before expressing interest?',"Eligible members can see permitted photos before sending interest, under the owner's permissions and the agreed membership policy."],['Will my contact details be shared with a match?','Your coordinator handles the family introduction with permission. Contact details are never released automatically.'],['Can my family help manage my profile?','Yes, with your authorisation. You can review or remove delegated access from your dashboard.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></section>${closing()}</main>${footer()}`;}
const cityByState={Karnataka:'Bengaluru',Kerala:'Kochi','Tamil Nadu':'Chennai','Andhra Pradesh':'Vijayawada',Telangana:'Hyderabad'};
function regionContent(s){return `<h3>${esc(s)}</h3><p>${cityByState[s]||''} and other cities on enquiry. Tell us about your preferred location.</p><button class="text-link" data-action="region-enquiry" data-region="${esc(s)}">Ask about ${esc(s)} ${arrow()}</button><p style="font-size:13px;margin-top:16px;opacity:.8">Regional enquiry options. Service availability is subject to confirmation.</p>`;}
const values=[['church','Faith at the centre','Space for your church life, everyday beliefs and the values you want to share.'],['people','Family, with clear permission','A defined role for the people supporting you, with your choices at the centre.'],['shield','Privacy through the process','Your contact details stay restricted, and photos follow the permission you give.'],['document','A considered review','Clear checks, specific correction requests and a connected view of your progress.']];
function about(){return `${header()}<main id="main"><section class="page-hero wrap"><div><div class="eyebrow">About Covenant Matrimony</div><h1>A thoughtful introduction begins with <em>understanding you.</em></h1><p>We bring Christian individuals and families into a guided process where faith is understood, privacy is respected and the next step is always a choice.</p><a href="#purpose" class="text-link" style="margin-top:24px">Get to know our approach ${arrow()}</a></div><div class="editorial-photo arch quad-0" role="img" aria-label="Illustrative Indian family having a warm conversation"></div></section><section class="quote-band wrap reveal" id="purpose"><div class="quote-mark">“</div><h2>Your profile helps introduce you.<br>Your story goes further.</h2><p>The person behind the profile</p></section><section class="narrative wrap reveal"><div class="editorial-photo quad-1" role="img" aria-label="Sunlit Indian church interior"></div><div><div class="eyebrow">Our purpose</div><h2>Room for honest conversations. And a life to build.</h2><p>Marriage is a personal decision with a lasting place in family life. The search for a partner should leave room for honest conversations about faith, values and the life two people hope to build together.</p><p>Your church community, your family relationships, your work and the language you speak all have a place in the process.</p><p>Begin online, with an approved branch or through a partner church. Every route enters the same system, so your information and introduction progress stay connected.</p></div></section><div class="values-grid wrap reveal">${values.map(([i,h,p])=>`<article class="value">${ic(i)}<div><h3>${h}</h3><p>${p}</p></div></article>`).join('')}</div><section class="people-section"><div class="wrap reveal"><div class="eyebrow">People, not just profiles</div><h2 style="margin-top:18px">You choose the next step.<br>We help you find your way.</h2><div class="people-grid">${[['01','The Covenant team','Review submissions, manage partner access and oversee your introduction journey.'],['02','Church & branch teams','Help consenting members begin, complete details and resolve profile tasks.'],['03','Your coordinator','An assigned pastor or representative helps arrange permitted family conversations and meetings.'],['04','You & your family','Choose what to share, who may assist and whether an introduction continues.']].map(([n,h,p])=>`<article class="person-role"><div class="role-num">${n}</div><h3>${h}</h3><p>${p}</p></article>`).join('')}</div></div></section><section class="narrative wrap reveal"><div><div class="eyebrow">Beyond the first response</div><h2>Guidance for the conversations that follow.</h2><p>Mutual interest is the beginning of a conversation. Your assigned coordinator helps with family introductions, meetings, feedback and the agreed counselling process as the relationship progresses.</p><a href="specialties.html" class="text-link">Explore what makes it personal ${arrow()}</a></div><div class="editorial-photo quad-2" role="img" aria-label="Illustrative pastor guiding a couple in conversation"></div></section>${closing('Let your next chapter begin<br>with understanding.','Tell us about yourself and what you hope to find. We will help you understand the next step.')}</main>${footer()}`;}
const specialties=[['church','Someone who understands your faith','Prayer, church life and the place faith holds in everyday decisions deserve a place in the conversation.','Share your faith preferences','preferences'],['people','Your family can support your choice','Give authorised family members a defined role, with your permission and response central to each introduction.','Understand family permissions','family'],['leaf','A human connection through your church','Church representatives can help you begin and confirm affiliation. Covenant completes the wider profile review.','Ask about church registration','church-enquiry'],['profile','See the person before the next step','Eligible members can see permitted photos before expressing interest, while contact details remain private.','Explore the member experience','login'],['heart','A guide for the family conversation','An assigned pastor or representative obtains permission and helps coordinate a thoughtful introduction.','Understand guided introductions','guided'],['pin','Language and location belong here','Discuss where you live, the language your family speaks and whether you are open to relocating.','Tell us where to begin','region-enquiry'],['book','Preparation for married life','Counselling creates space to talk about expectations, responsibilities and the life you hope to build together.','Ask about counselling','counselling'],['clock','A respectful pace. A clear next step.','Accept, decline or pause. See what has happened and what needs your attention, at a pace that respects you.','Create your profile','register']];
const specialtyImages=[['stories-1','A sunlit church interior'],['stories-0','A couple in conversation with their parents'],['stories-1','A church community setting'],['portraits-3','An illustrative member portrait'],['stories-0','A thoughtful family conversation'],['stories-3','A couple walking together outdoors'],['stories-2','A pastor guiding a couple in conversation'],['hero','An Indian Christian wedding couple']];
function carouselToolbar(copy,id,action='carousel-scroll'){return `<div class="carousel-toolbar"><p>${copy}</p><div class="carousel-controls"><span data-carousel-position="${id}" aria-live="polite">1 / 8</span><button class="carousel-arrow previous" data-action="${action}" data-track="${id}" data-direction="-1" aria-label="${action==='journey-step'?'Previous stage':'Previous cards'}" aria-controls="${id}">${arrow()}</button><button class="carousel-arrow" data-action="${action}" data-track="${id}" data-direction="1" aria-label="${action==='journey-step'?'Next stage':'Next cards'}" aria-controls="${id}">${arrow()}</button></div></div>`;}
function specialtyPage(){return `${header()}<main id="main"><section class="specialty-intro"><div class="eyebrow">What makes the journey personal</div><h1>Shared faith matters.<br><em>So does the life you hope to build.</em></h1><p>A meaningful introduction considers more than a name and a photograph. It makes room for your beliefs, your family and the choices that shape married life.</p></section><div class="specialty-hero-image wrap"><img src="assets/stories-3.webp" alt="Illustrative Indian couple walking together through a garden" fetchpriority="high"></div><section class="specialty-carousel-section wrap" aria-label="Our eight specialties">${carouselToolbar('Eight ways we make the journey personal.','specialty-track')}<div class="specialty-grid photo-carousel" id="specialty-track" data-carousel-track tabindex="0" role="list" aria-label="Eight Christian matrimony specialties">${specialties.map(([i,h,p,c,a],n)=>`<article class="specialty-card" role="listitem" tabindex="0"><img class="specialty-card-image" src="assets/${specialtyImages[n][0]}.webp" alt="Illustrative ${specialtyImages[n][1].toLowerCase()}" loading="lazy"><div class="specialty-card-copy"><div class="topline"><span>0${n+1} / WHAT MATTERS</span>${ic(i)}</div><h3>${h}</h3><p>${p}</p><button class="text-link" data-action="${a}">${c} ${arrow()}</button></div></article>`).join('')}</div><p class="carousel-hint">Swipe, scroll or use the arrows to explore all eight specialties.</p></section>${closing('Find room for<br>what matters to you.','Share the faith, family and life preferences you want an introduction to respect.')}</main>${footer()}`;}

function loginPage(){return `<main id="main" class="login-layout"><aside class="login-visual">${brand()}<div><div class="eyebrow light" style="margin-bottom:20px">Your next chapter</div><h2>A shared faith.<br><em>A life together.</em></h2><p>A thoughtful journey, with people to guide you and choices that stay yours.</p><div class="caption">COVENANT MATRIMONY · ILLUSTRATIVE PHOTOGRAPHY</div></div></aside><section class="login-pane"><a class="back-link" href="index.html">${ic('arrow')} Back to Covenant</a><div class="login-box"><div class="eyebrow">Your Covenant workspace</div><h1>Welcome back.</h1><p>Sign in to continue your journey.</p><div class="role-tabs" role="tablist" aria-label="Choose a demo workspace">${Object.keys(accounts).map(r=>`<button class="role-tab" role="tab" aria-selected="${r===loginRole}" data-role="${r}">${r==='admin'?'Admin':r[0].toUpperCase()+r.slice(1)}</button>`).join('')}</div><form id="login-form"><div class="field"><label for="email">Email address</label><input id="email" name="email" type="email" required autocomplete="username" value="${accounts[loginRole].email}"></div><div class="field"><label for="password">Password</label><div class="password-field"><input id="password" name="password" type="password" required autocomplete="current-password" value="${password}"><button type="button" data-action="show-password">Show</button></div></div><div class="form-error" id="login-error" role="alert"></div><button class="btn full" type="submit">Enter ${loginRole==='admin'?'super admin':loginRole} workspace ${arrow()}</button></form><div class="login-help"><button data-action="recovery">Forgot password?</button><button data-action="register">New here? Create a profile</button></div><div class="demo-note"><strong>Explore the showcase</strong><br>Demo credentials are filled in for you. Switch tabs to explore the member, branch, church or admin workspace.<br><span style="font-size:14px">Mock data only. Please use fictional details.</span></div></div></section></main>`;}
const navs={member:[['overview','home','Overview'],['profile','profile','My profile'],['discover','search','Discover'],['interests','heart','Interests'],['introductions','people','My introductions'],['appointments','calendar','Appointments'],['membership','key','Membership'],['privacy','shield','Privacy & support']],branch:[['overview','home','Overview'],['profiles','people','Member directory'],['add','plus','Add member profile'],['reviews','document','Submission queue'],['introductions','heart','Introduction updates'],['tasks','list','Tasks'],['staff','settings','Staff']],church:[['overview','home','Overview'],['profiles','people','Church members'],['add','plus','Add member profile'],['confirmations','checkCircle','Confirmations'],['introductions','heart','Match updates'],['tasks','list','Tasks'],['staff','settings','Staff']],admin:[['overview','home','Overview'],['reviews','document','Profiles & review'],['profiles','people','Members'],['organisations','branch','Branches & churches'],['partners','church','Partner applications'],['introductions','heart','Introductions'],['appointments','calendar','Appointments'],['membership','key','Membership'],['content','globe','Website content'],['reports','chart','Reports'],['audit','shield','Roles & audit']]};
function dashboard(){const active=(navs[user.role].find(n=>n[0]===view)||navs[user.role][0]);view=active[0];const pending=state.interests.filter(i=>i.to===user.profileId&&i.status==='Pending').length;return `<div class="app-shell"><aside class="sidebar">${brand()}<div class="workspace-label">${user.role==='admin'?'Super admin':user.role} workspace</div><nav class="side-nav" aria-label="Workspace navigation">${navs[user.role].map(([id,i,n])=>`<button data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${ic(i)}<span>${n}</span>${id==='interests'&&pending?`<span class="nav-count">${pending}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note">Every next step<br>is a choice.</div><div class="side-user"><div class="initials">${user.name.split(' ').map(n=>n[0]).slice(0,2).join('')}</div><div><strong>${esc(user.name)}</strong><small>${esc(user.orgName||'Covenant member')}</small></div></div><button class="logout" data-action="logout">${ic('logout')} Sign out / switch demo</button></div></aside><div class="app-main"><header class="app-topbar"><button class="menu-button" data-action="sidebar" aria-label="Open workspace navigation" aria-expanded="false">${ic('menu')}</button><div class="breadcrumb"><span class="workspace-crumb">${user.role==='admin'?'Covenant central':esc(user.orgName||'Your journey')}</span><span class="workspace-crumb">/</span><strong>${active[2]}</strong></div><div class="topbar-actions"><span class="preview-badge">Demo workspace</span><button class="notification-btn" data-action="notifications" aria-label="View notifications">${ic('bell')}</button><div class="initials">${user.name.split(' ').map(n=>n[0]).slice(0,2).join('')}</div></div></header><main id="main" class="app-content view-enter">${renderView()}<div class="app-footer"><span>Covenant Matrimony · ${config.backend==='php'?'PHP session demo':'Illustrative demo data'}</span><span>Your permissions. Your pace. Your journey.</span></div></main></div></div>`;}
const heading=(title,copy='',action='')=>`<div class="dash-heading"><div><div class="eyebrow">${user.role==='member'?'Your Covenant journey':esc(user.orgName||'Covenant central')}</div><h1>${title}</h1>${copy?`<p>${copy}</p>`:''}</div>${action||`<div class="date-pill">${ic('calendar')}${new Date().toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric'})}</div>`}</div>`;
const stat=(label,value,foot,i='heart')=>`<article class="stat-card">${ic(i)}<div class="stat-label">${label}</div><div class="stat-value ${typeof value==='string'&&value.length>5?'word':''}">${value}</div><div class="stat-foot">${foot}</div></article>`;
const panel=(title,body,action='')=>`<section class="panel"><div class="panel-head"><h2>${title}</h2>${action}</div><div class="panel-body">${body}</div></section>`;
const viewLink=(v,t='View all')=>`<button class="text-link" data-view="${v}">${t} ${arrow()}</button>`;
const empty=(title,copy,i='leaf')=>`<div class="empty">${ic(i)}<h3>${title}</h3><p>${copy}</p></div>`;
function timeline(c){const stages=['Mutual interest confirmed','Coordinator assigned','Family contact authorised','Meeting & feedback','Premarital counselling','Moving towards marriage'];let idx=c.coordinator?1:0;if(c.stage==='Family contact authorised')idx=2;return `<div class="timeline">${stages.map((s,i)=>`<div class="timeline-step ${i<idx?'done':i===idx?'current':''}">${s}<small>${i===idx?'Your current step':i<idx?'Completed':'When you are ready'}</small></div>`).join('')}</div>`;}
function miniInterests(){const list=state.interests.filter(i=>i.to===user.profileId&&i.status==='Pending');return list.length?list.map(i=>{const p=profileById(i.from);if(!p)return '';return `<div class="profile-mini-row">${avatar(p)}<div><h3>${esc(p.name)}</h3><p>${p.age} · ${esc(p.city)} · ${esc(p.career)}</p></div><div class="row-actions"><button class="btn outline small" data-action="profile-detail" data-id="${p.id}">View</button><button class="btn small" data-action="respond-interest" data-id="${i.id}" data-response="Accepted">Accept</button></div></div>`;}).join(''):empty('You’re all caught up','New interest requests will appear here.');}
function memberOverview(){const mine=profileById(user.profileId);const cases=scopedCases(state,user);const received=state.interests.filter(i=>i.to===user.profileId&&i.status==='Pending').length;const ap=state.appointments.find(a=>a.profile===user.profileId);return `${heading('Hello, '+esc(user.name.split(' ')[0])+'.','A little closer to the next chapter. Here is where you are today.')}<section class="welcome-banner"><div><div class="eyebrow">${mine.status==='Approved'?'Your profile is ready':'Your profile needs a little attention'}</div><h2>${mine.status==='Approved'?'A thoughtful beginning awaits.':'Let’s complete the next step.'}</h2><p>${mine.status==='Approved'?'Discover people who share your faith and your hopes for a life together.':'Review your details and submit your profile when the required information is ready.'}</p></div><button class="btn light small" data-view="${mine.status==='Approved'?'discover':'profile'}">${mine.status==='Approved'?'Explore profiles':'Review my profile'} ${arrow()}</button></section><div class="stats-grid">${stat('Profile status',mine.status,'Central review status','shield')}${stat('New interests',received,'Awaiting your response','heart')}${stat('Guided introductions',cases.length,'A next step, together','people')}${stat('Appointments',state.appointments.filter(a=>a.profile===user.profileId).length,'Your upcoming conversations','calendar')}</div><div class="dash-grid"><div>${panel('People interested in you',miniInterests(),viewLink('interests'))}<div style="height:22px"></div>${panel('Your introduction journey',cases.length?`<div style="display:flex;justify-content:space-between;gap:15px;margin:3px 0 25px"><div><h3 style="font-size:27px;color:var(--green)">You & ${esc(profileById(cases[0].pair.find(id=>id!==user.profileId))?.name||'your introduction')}</h3><p style="font-size:15px;margin-top:8px">${cases[0].coordinator?'Guided by '+esc(cases[0].coordinator):'Your coordinator will be assigned shortly'}</p></div>${badge(cases[0].stage)}</div>${timeline(cases[0])}`:empty('Your next chapter is open','Mutual interest begins a guided introduction.'),viewLink('introductions','View journey'))}</div><div><section class="progress-card"><div class="top">${avatar(mine)}<div><h3>${esc(mine.name)}</h3><p>${mine.id} · ${esc(mine.city)}</p></div></div><div class="progress-text"><span>Profile readiness</span><strong>${mine.evidence&&mine.consent?'100':'75'}%</strong></div><div class="progress-bar"><span style="width:${mine.evidence&&mine.consent?'100':'75'}%"></span></div><p>Your details, faith and preferences help an introduction feel personal.</p><button class="text-link" data-view="profile" style="font-size:14px;margin-top:10px">Review my profile ${arrow()}</button></section>${panel('Your next steps',`<div class="todo-list"><div class="todo">${ic('heart')}<div>Review ${received} interest ${received===1?'request':'requests'}<small>Choose whether to continue.</small></div><button data-view="interests">Review</button></div><div class="todo">${ic('shield')}<div>Family contact permission<small>Personal details stay private.</small></div><button data-view="introductions">Manage</button></div></div>${ap?`<div class="appointment-card"><div class="date-block"><strong>${Number(ap.date.slice(-2))}</strong><small>${new Date(ap.date+'T12:00:00').toLocaleDateString('en',{month:'short'}).toUpperCase()}</small></div><div><h3>Meet your coordinator</h3><p>${ap.time} · ${esc(ap.type)}</p></div></div>`:''}`,viewLink('appointments','View dates'))}<div class="privacy-card">${ic('shield')}<div><strong>Your contact details stay private.</strong>Mutual interest does not share your contact information. Your permission comes first.</div></div></div></div>`;}
function partnerOverview(){const ps=visibleProfiles(state,user),consent=ps.filter(p=>!p.consent).length,reviews=ps.filter(p=>p.status==='Under review').length,corrections=ps.filter(p=>p.status==='Changes requested').length;const ts=state.tasks.filter(t=>t.org===user.org&&!t.done);return `${heading(user.role==='church'?'A place to begin, together.':'A personal start for every member.','Manage consenting members and keep the next step clear.',`<button class="btn small" data-view="add">${ic('plus')} Add member</button>`)}<section class="welcome-banner"><div><div class="eyebrow">${user.role==='church'?'Your church community':'Your branch, connected'}</div><h2>Help a thoughtful introduction begin.</h2><p>Support your members, resolve outstanding details and follow the progress you are authorised to see.</p></div><button class="btn light small" data-view="profiles">View members ${arrow()}</button></section><div class="stats-grid">${stat('Managed profiles',ps.length,'Within your permitted directory','people')}${stat('Awaiting consent',consent,'Member permission needed','shield')}${stat('Central review',reviews,'Submitted to Covenant','document')}${stat('Corrections needed',corrections,'Help with the next step','list')}</div><div class="dash-grid"><div>${directoryPanel(ps.slice(0,5),'Your member directory',viewLink('profiles'))}<div style="height:22px"></div>${panel('Intake at a glance',bars(ps))}</div><div>${panel('Needs your attention',`<div class="todo-list">${ts.map(t=>`<div class="todo">${ic('clock')}<div>${esc(t.title)}<small>${t.profile} · ${user.role==='church'?'Church support':'Branch support'}</small></div><button data-view="tasks">Open</button></div>`).join('')||'<p style="font-size:16px">No outstanding tasks.</p>'}</div>`)}<div style="height:22px"></div>${panel('One connected review process',`<div class="timeline"><div class="timeline-step done">Create a profile draft<small>Record the original intake route.</small></div><div class="timeline-step current">Confirm member authority<small>The member confirms their permissions.</small></div><div class="timeline-step">Submit to central review<small>Consent and evidence are required.</small></div><div class="timeline-step">Published when eligible<small>Covenant approves the profile.</small></div></div>`)}<div class="privacy-card">${ic('shield')}<div><strong>Access follows permission.</strong>Your directory includes only the members you are authorised to manage.</div></div></div></div>`;}
function bars(ps){const totals=['online','branch','church'].map(r=>[r,ps.filter(p=>p.route===r).length]);return `<div class="metric-bars">${totals.map(([r,n])=>`<div class="metric-row"><span>${r[0].toUpperCase()+r.slice(1)}</span><div class="bar"><span style="width:${n/Math.max(ps.length,1)*100}%"></span></div><strong>${n}</strong></div>`).join('')}</div><p style="font-size:13px;color:#88957c">Counts reflect the current demo profiles and their original intake route.</p>`;}
function adminOverview(){const awaiting=state.profiles.filter(p=>p.status==='Under review'),assign=state.cases.filter(c=>!c.coordinator),consent=state.profiles.filter(p=>!p.consent).length;return `${heading('Every journey, connected.','One shared system. A considered review. Clear permission at every step.')}<section class="welcome-banner"><div><div class="eyebrow">Central oversight</div><h2>The next step starts with your team.</h2><p>${awaiting.length} profiles are awaiting central review. ${assign.length} ${assign.length===1?'introduction needs':'introductions need'} a coordinator.</p></div><button class="btn light small" data-view="reviews">Open review queue ${arrow()}</button></section><div class="stats-grid">${stat('Total profiles',state.profiles.length,'Across all three intake routes','people')}${stat('Review backlog',awaiting.length,'Consent recorded · evidence ready','document')}${stat('Awaiting assignment',assign.length,'Mutual interest confirmed','heart')}${stat('Awaiting consent',consent,'Unpublished assisted drafts','shield')}</div><div class="dash-grid"><div>${directoryPanel(awaiting,'Ready for your review',viewLink('reviews','View review queue'))}<div style="height:22px"></div>${panel('Intake by original route',bars(state.profiles))}</div><div>${panel('Introduction worklist',state.cases.map(c=>`<div class="profile-mini-row"><div class="initials">${ic('heart')}</div><div><h3>${esc(c.pair.map(id=>profileById(id)?.name?.split(' ')[0]||id).join(' & '))}</h3><p>${esc(c.stage)}</p></div><button class="text-link" style="font-size:14px;border:0;margin-left:auto" data-view="introductions">Open ${arrow()}</button></div>`).join(''),viewLink('introductions'))}<div style="height:22px"></div>${panel('Recent activity',auditBody().slice(0,2500),viewLink('audit'))}<div class="privacy-card">${ic('shield')}<div><strong>Oversight with clear boundaries.</strong>Profile approval, contact permission and membership are separate decisions.</div></div></div></div>`;}
function directoryPanel(ps,title='Member directory',action=''){return `<section class="panel"><div class="panel-head"><h2>${title}</h2>${action}</div>${ps.length?`<div class="table-wrap"><table class="directory"><thead><tr><th>Member</th><th>Original route</th><th>Status</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr data-searchable="${esc((p.name+' '+p.id+' '+p.city).toLowerCase())}" data-status="${p.status}" data-route="${p.route}"><td><div class="person-cell">${avatar(p)}<div><strong>${esc(p.name)}</strong><small>${p.id} · ${esc(p.city)}</small></div></div></td><td><span class="source-chip">${ic(p.route==='online'?'globe':p.route)}${p.route[0].toUpperCase()+p.route.slice(1)}</span></td><td>${badge(p.status)}</td><td><button class="text-link" data-action="managed-detail" data-id="${p.id}">${user.role==='admin'?'Review':'View'} ${arrow()}</button></td></tr>`).join('')}</tbody></table></div>`:empty('Nothing waiting here','Profiles will appear when there is a next step to take.')}<div class="table-note">${user.role==='admin'?'Central review across all intake routes.':'Only members within your management authority are shown.'}</div></section>`;}
function directoryView(isReview=false){let ps=visibleProfiles(state,user);if(isReview)ps=ps.filter(p=>['Under review','Changes requested','Awaiting consent'].includes(p.status));return `${heading(isReview?(user.role==='admin'?'Profiles & central review':'Submission queue'):(user.role==='church'?'Your church members':'Member directory'),'Clear states, connected records and one next action.',user.role==='admin'?'':`<button class="btn small" data-view="add">${ic('plus')} Add member</button>`)}<div class="toolbar"><div class="search-field">${ic('search')}<input aria-label="Search member name, ID or city" data-search placeholder="Search name, profile ID or city…"></div><div class="actions"><select class="filter" data-filter="status" aria-label="Filter by status"><option value="">All statuses</option>${[...new Set(ps.map(p=>p.status))].map(s=>`<option>${s}</option>`).join('')}</select><select class="filter" data-filter="route" aria-label="Filter by original route"><option value="">All routes</option><option value="online">Online</option><option value="branch">Branch</option><option value="church">Church</option></select></div></div>${directoryPanel(ps,isReview?'Profiles needing a next step':'Managed member profiles')}<p id="filter-empty" class="empty" hidden>No profiles match these filters.</p>`;}
function discoverView(){const list=discovery(state,user);return `${heading('People to consider.','Your faith and preferences are a thoughtful place to begin.',`<button class="btn outline small" data-action="preferences">${ic('settings')} Preferences</button>`)}<div class="toolbar"><div class="search-field">${ic('search')}<input aria-label="Search profiles" data-search placeholder="Search name, city or profession…"></div><select class="filter" data-filter="state" aria-label="Filter profiles by state"><option value="">All states</option>${states.map(s=>`<option>${s}</option>`).join('')}</select></div><div class="profile-grid">${list.map(p=>`<article class="match-card" data-searchable="${esc((p.name+' '+p.city+' '+p.career).toLowerCase())}" data-state="${p.state}"><div class="match-photo quad-${p.portrait}" role="img" aria-label="Illustrative portrait of ${esc(p.name)}"><span class="badge">${ic('shield')} Profile reviewed</span></div><div class="details"><h3>${esc(p.name)}</h3><p>${p.age} years · ${esc(p.city)}, ${esc(p.state)}</p><p>${esc(p.career)}</p><div class="match-meta"><span>${esc(p.denomination)}</span><span>${esc(p.language)}</span></div><div class="match-actions"><button class="btn outline small" data-action="profile-detail" data-id="${p.id}">View profile</button><button class="btn small" data-action="send-interest" data-id="${p.id}">${hasInterest(p.id)?'Interest sent':'Express interest'}</button></div></div></article>`).join('')}</div>${!list.length?empty('Your search can wait','Complete your profile review and visibility permission before exploring introductions.'):''}<p id="filter-empty" class="empty" hidden>No profiles match these filters.</p><div class="inline-note">${ic('shield')}Contact details stay private. Expressing interest invites a response.</div>`;}
function hasInterest(id){return state.interests.some(i=>i.from===user.profileId&&i.to===id&&['Pending','Accepted'].includes(i.status));}
function interestsView(){const list=state.interests.filter(i=>interestTab==='received'?i.to===user.profileId:i.from===user.profileId);return `${heading('A choice to take the next step.','Review each introduction at a pace that feels right.')}<div class="tab-line"><button class="${interestTab==='received'?'active':''}" data-interest-tab="received">Received interests</button><button class="${interestTab==='sent'?'active':''}" data-interest-tab="sent">Sent interests</button></div>${panel(interestTab==='received'?'People interested in you':'Your expressions of interest',list.map(i=>{const p=profileById(interestTab==='received'?i.from:i.to);if(!p)return '';return `<div class="profile-mini-row">${avatar(p)}<div><h3>${esc(p.name)}</h3><p>${p.age} · ${esc(p.city)} · ${esc(p.career)}</p></div><div class="row-actions">${i.status==='Pending'?`<button class="btn outline small" data-action="profile-detail" data-id="${p.id}">View</button>${interestTab==='received'?`<button class="btn small" data-action="respond-interest" data-id="${i.id}" data-response="Accepted">Accept</button><button class="btn outline small" data-action="respond-interest" data-id="${i.id}" data-response="Declined">Decline</button>`:`<button class="btn outline small" data-action="respond-interest" data-id="${i.id}" data-response="Withdrawn">Withdraw</button>`}`:badge(i.status)}</div></div>`;}).join('')||empty('No interests here yet','Thoughtful introductions begin with one small step.'))}<div class="inline-note">${ic('shield')}Acceptance creates mutual interest and a coordinator assignment request. Your contact details remain private.</div>`;}
function introductionView(){const cs=scopedCases(state,user);return `${heading(user.role==='member'?'Your introduction journey.':'Guided introductions.','A shared next step, with clear permission and personal guidance.')}${cs.map(c=>`<article class="case-card"><div class="case-top"><div><div class="eyebrow" style="font-size:12px;margin-bottom:12px">${c.id}</div><h2>${esc(c.pair.map(id=>profileById(id)?.name||id).join(' & '))}</h2><p>${c.coordinator?'Guided by '+esc(c.coordinator):'A coordinator will be assigned by Covenant.'}</p></div>${badge(c.stage)}</div><div class="case-grid">${timeline(c)}<div class="case-callout"><h3>${c.coordinator?'A conversation, with permission.':'A guide for your next step.'}</h3><p>${c.coordinator?'Your coordinator can connect families only when both members have authorised contact.':'Mutual interest is confirmed. Central staff will assign the person guiding this introduction.'}</p>${user.role==='member'?`<div class="settings-row" style="border:0"><div><h3>My family contact permission</h3><p>${c.contact[user.profileId]?'You have granted permission. The other member’s permission is still checked.':'Your family’s details remain private.'}</p></div><button class="switch" role="switch" aria-checked="${!!c.contact[user.profileId]}" aria-label="Authorise family contact for ${c.id}" data-action="contact-consent" data-id="${c.id}" ${!c.coordinator?'disabled':''}></button></div>`:user.role==='admin'?`<div class="actions"><button class="btn small" data-action="assign" data-id="${c.id}">${c.coordinator?'Reassign coordinator':'Assign coordinator'} ${arrow()}</button></div>`:`<div class="inline-note">${ic('shield')}Contact access requires consent from both participants.</div>`}</div></div></article>`).join('')||panel('Your introduction worklist',empty('No introductions here yet',user.role==='member'?'When interest is mutual, your guided journey begins.':'Assigned cases and authorised progress updates will appear here.'))}`;}
function profileView(){const p=profileById(user.profileId);return `${heading('The person behind your profile.','Share what matters to you, your family and your future.') }<div class="form-panel"><div class="profile-mini-row" style="padding-top:0;border:0;margin-bottom:25px">${avatar(p,'large')}<div><h3>${esc(p.name)}</h3><p>${p.id} · ${esc(p.route)} registration</p></div><div style="margin-left:auto">${badge(p.status)}</div></div><form id="profile-form"><h2>Your personal details</h2><div class="form-grid">${field('name','Full name',p.name)}${field('career','Profession',p.career)}${field('city','City',p.city)}${selectField('state','State',states,p.state)}${field('language','Language',p.language)}${field('faith','Faith community',p.denomination,'text','readonly')}<div class="field span-2"><label for="bio">A little about you</label><textarea id="bio" name="bio" maxlength="800">${esc(p.bio)}</textarea></div></div><div class="inline-note">${ic('shield')}Changes to reviewed details return to central review before discovery.</div><div class="form-error" role="alert"></div><div class="actions"><button class="btn small" type="submit">Save details ${arrow()}</button><button type="button" class="btn outline small" data-action="submit-profile" data-id="${p.id}">Submit for review</button></div></form><h3>Evidence & permissions</h3><div class="settings-row"><div><h3>Identity and age evidence</h3><p>${p.evidence?'Illustrative evidence is recorded for this demo profile.':'Required evidence is outstanding. Your assisted registration team will help.'}</p></div>${badge(p.evidence?'Recorded':'Pending')}</div><div class="settings-row"><div><h3>Profile submission permission</h3><p>You choose whether your details can be submitted for central review.</p></div><button class="switch" role="switch" aria-checked="${p.consent}" aria-label="Profile submission consent" data-action="submission-consent" data-id="${p.id}"></button></div><div class="settings-row"><div><h3>Family managers</h3><p>No family managers have been authorised for this demo profile.</p></div><button class="text-link" data-action="family">Learn more</button></div></div>`;}
let fieldSequence=0;
function field(n,l,v='',type='text',extra=''){const inputId=n+'-'+(++fieldSequence);return `<div class="field"><label for="${inputId}">${l}</label><input id="${inputId}" name="${n}" type="${type}" value="${esc(v)}" ${extra} ${['name','city','career'].includes(n)?'required':''} maxlength="${type==='number'?'2':'100'}"></div>`;}
function selectField(n,l,options,current=''){const inputId=n+'-'+(++fieldSequence);return `<div class="field"><label for="${inputId}">${l}</label><select id="${inputId}" name="${n}">${options.map(o=>`<option ${o===current?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`;}
function addProfileView(){return `${heading('A thoughtful beginning.','Create a draft for a member you are authorised to assist.')}<div class="form-panel"><div class="eyebrow" style="margin-bottom:25px;font-size:13px">${user.role==='church'?'Church':'Branch'} assisted registration</div><form id="add-form"><div class="form-grid">${field('name','Member full name')}${field('age','Age','','number','min="21" max="80" required')}${selectField('gender','Gender',['Female','Male'])}${field('city','City')}${selectField('state','State',states)}${field('career','Profession')}${selectField('denomination','Faith community',['Protestant','Catholic','Orthodox','Other Christian'])}<div class="field"><label>Original organisation</label><input value="${esc(user.orgName)}" readonly></div></div><label class="check"><input name="authority" type="checkbox" required><span>I have permission to create this draft and invite the member to confirm their details.</span></label><div class="demo-note">The draft remains unpublished. Member confirmation, evidence and central approval are separate next steps.</div><div class="form-error" role="alert"></div><button class="btn" type="submit">Save member draft ${arrow()}</button></form></div>`;}
function tasksView(){const ts=state.tasks.filter(t=>t.org===user.org);return `${heading('Keep the next step clear.','Your profile and member support tasks.')}${panel('Your worklist',ts.map(t=>`<div class="profile-mini-row"><div class="initials">${ic(t.done?'check':'clock')}</div><div><h3>${esc(t.title)}</h3><p>${t.profile} · ${t.done?'Completed':'Open task'}</p></div><div class="row-actions"><button class="btn outline small" data-action="task" data-id="${t.id}" data-done="${!t.done}">${t.done?'Reopen':'Mark done'}</button></div></div>`).join('')||empty('All clear','You have no tasks at the moment.'))}<div class="inline-note">${ic('shield')}Completing a task does not create member consent or change central approval.</div>`;}
function confirmationsView(){const ps=visibleProfiles(state,user);return `${heading('Church context, carefully recorded.','Affiliation confirmation is one check within the wider profile review.')}${panel('Member affiliation',ps.map(p=>`<div class="profile-mini-row">${avatar(p)}<div><h3>${esc(p.name)}</h3><p>${p.id} · ${p.confirmedBy?'Confirmed by '+esc(p.confirmedBy):'Church affiliation '+esc(p.affiliation.toLowerCase())}</p></div><div class="row-actions">${badge(p.affiliation)}<button class="btn outline small" data-action="confirm-affiliation" data-id="${p.id}">Record confirmation</button></div></div>`).join(''))}<div class="inline-note">${ic('shield')}Church confirmation does not replace identity, age evidence or central approval.</div>`;}
function appointmentsView(){const list=user.role==='admin'?state.appointments:state.appointments.filter(a=>a.profile===user.profileId);return `${heading('Conversations worth making time for.','Family meetings, coordinator conversations and counselling.')}${list.map(a=>panel(esc(a.title),`<div class="appointment-card" style="margin:0 0 22px"><div class="date-block"><strong>${Number(a.date.slice(-2))}</strong><small>${new Date(a.date+'T12:00:00').toLocaleDateString('en',{month:'short'}).toUpperCase()}</small></div><div><h3>${new Date(a.date+'T12:00:00').toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long'})}</h3><p>${a.time} · ${a.type}</p></div><div style="margin-left:auto">${badge(a.status)}</div></div>${user.role==='member'?`<div class="actions"><button class="btn small" data-action="appointment" data-id="${a.id}" data-status="Confirmed">Confirm appointment</button><button class="btn outline small" data-action="appointment" data-id="${a.id}" data-status="Change requested">Request another time</button></div>`:`<div class="inline-note">${ic('calendar')}Member ${a.profile} · Appointment responses are recorded in the member workspace.</div>`}`)).join('')||panel('Appointments',empty('No dates to keep yet','Your arranged conversations will appear here.','calendar'))}`;}
function membershipView(){const m=state.membership;return `${heading('Your annual membership.','A separate record from profile approval and introduction progress.')}<section class="membership-card"><div class="eyebrow">Covenant annual membership</div><h2>A year of<br>thoughtful possibilities.</h2>${badge(m.status)}<p>Annual membership structure is being finalised. Pricing, benefits and access conditions will be confirmed separately.</p><div class="rule"></div><p>${m.status==='Active'?`Demo period: ${m.start} to ${m.end}.`:'No payment is requested in this showcase.'}</p>${user.role==='admin'?`<button class="btn light small" style="margin-top:25px" data-action="membership-grant">Record an annual demo grant ${arrow()}</button>`:''}</section><div class="inline-note">${ic('shield')}Membership does not create consent or approve a matrimonial profile.</div>`;}
function privacyView(){const p=profileById(user.profileId);return `${heading('Your permission. Your pace.','Review what you share and how your profile can be seen.')}<div class="form-panel"><h2>Your visibility settings</h2><div class="settings-row"><div><h3>Allow my profile in discovery</h3><p>Eligible members can discover your approved profile. Turn this off to pause visibility.</p></div><button class="switch" role="switch" aria-label="Allow discovery" aria-checked="${p.visibility}" data-action="privacy" data-key="discovery"></button></div><div class="settings-row"><div><h3>Show my permitted photos</h3><p>Eligible members may see your photos before expressing interest.</p></div><button class="switch" role="switch" aria-label="Photo visibility" aria-checked="${p.photoVisible}" data-action="privacy" data-key="photos"></button></div><div class="settings-row"><div><h3>Family contact permissions</h3><p>Manage these separately for each introduction, after a coordinator is assigned.</p></div><button class="text-link" data-view="introductions">Manage ${arrow()}</button></div><div class="settings-row"><div><h3>Need a hand?</h3><p>Ask about the process or a profile task.</p></div><button class="text-link" data-action="support">Ask for support</button></div></div>`;}
function staffView(){return `${heading('The people assisting your members.','Staff access stays within your organisation and assigned work.')}${panel('Authorised representatives',state.staff.filter(s=>s.org===user.org).map(s=>`<div class="profile-mini-row"><div class="initials">${esc(s.name.split(' ').map(n=>n[0]).join(''))}</div><div><h3>${esc(s.name)}</h3><p>${esc(s.role)} · ${esc(user.orgName)}</p></div><div style="margin-left:auto">${badge('Active')}</div></div>`).join(''))}<div class="inline-note">${ic('shield')}Staff roles and revocation are controlled centrally in this showcase.</div>`;}
function organisationsView(){return `${heading('Your partner network.','Approved organisations, scoped access and connected intake.')}<div class="profile-grid">${state.organisations.map(o=>`<article class="form-panel" style="padding:25px">${ic(o.type)}<h3 style="font-family:var(--serif);font-size:26px;margin:20px 0 10px">${esc(o.name)}</h3><p style="font-size:15px;margin-bottom:15px">${o.id} · ${o.type[0].toUpperCase()+o.type.slice(1)} partner</p>${badge(o.status)}<div style="margin-top:20px"><button class="btn outline small" data-action="org-status" data-id="${o.id}">${o.status==='Active'?'Suspend access':'Restore access'}</button></div></article>`).join('')}</div><div class="inline-note">${ic('shield')}Suspending a partner revokes its workspace access. Member records remain in the central system.</div>`;}
function partnersView(){const es=state.enquiries.filter(e=>['church','branch'].includes(e.type));return `${heading('Partner applications.','An enquiry begins a review; it does not grant member access.')}${panel('Organisation enquiries',es.map(e=>`<div class="audit-row">${ic(e.type)}<div><strong>${esc(e.organisation||e.name)}</strong><p style="font-size:15px">${esc(e.message||'Interested in '+e.type+' registration')}</p><small>${esc(e.state||'Location to confirm')} · ${esc(e.email)} · Under review</small></div></div>`).join('')||empty('No partner enquiries yet','Use the church or branch entry options on the website to create a fictional enquiry.'))}`;}
function auditBody(){return state.audit.slice(0,15).map(a=>`<div class="audit-row">${ic('checkCircle')}<div>${esc(a.message)}<small>${esc(a.actor)} · ${new Date(a.date).toLocaleString('en-IN')}</small></div></div>`).join('')||`<div class="audit-row">${ic('shield')}<div>Your next sensitive action will appear here.<small>Review decisions, assignment, consent and membership grants.</small></div></div>`;}
function reportsView(){return `${heading('A clear view of the work.','Current demo intake, review stages and assignment progress.')}<div class="stats-grid">${stat('All profiles',state.profiles.length,'Canonical profile records','people')}${stat('Approved',state.profiles.filter(p=>p.status==='Approved').length,'Still subject to visibility permission','checkCircle')}${stat('Mutual introductions',state.cases.length,'One active case per pair','heart')}${stat('Pending assignments',state.cases.filter(c=>!c.coordinator).length,'Central worklist','list')}</div><div class="dash-grid">${panel('Original intake routes',bars(state.profiles))}${panel('Profile states',`<div class="metric-bars">${['Approved','Under review','Awaiting consent','Changes requested','Suspended'].map(s=>`<div class="metric-row review-metric"><span>${s}</span><div class="bar"><span style="width:${state.profiles.filter(p=>p.status===s).length/Math.max(1,state.profiles.length)*100}%"></span></div><strong>${state.profiles.filter(p=>p.status===s).length}</strong></div>`).join('')}</div>`)}</div><div class="actions" style="margin-top:24px"><button class="btn outline small" data-action="export-report">${ic('document')} Download PDF report</button></div>`;}
function contentView(){return `${heading('The Covenant website.','Three pages, one visual language and a considered public story.')}${panel('Page content', [['Home','index.html','The beginning, entry routes, eight-stage journey and regional enquiry.'],['About us','about.html','Our purpose, privacy and the people guiding each introduction.'],['Our specialties','specialties.html','Faith, family, language and preparation for married life.']].map(([n,h,p])=>`<div class="profile-mini-row"><div class="initials">${ic('globe')}</div><div><h3>${n}</h3><p>${p}</p></div><a class="text-link" style="margin-left:auto;border:0;font-size:14px" href="${h}" target="_blank" rel="noopener">Open page ${arrow()}</a></div>`).join(''))}<div class="demo-note"><strong>Publication review</strong><br>The showcase uses approved blueprint copy. Regional options are enquiries, and no office, endorsement or success claim is implied. Editing and publishing website copy will be connected to a CMS in the production build.</div>`;}
function renderView(){switch(view){case'overview':return user.role==='member'?memberOverview():user.role==='admin'?adminOverview():partnerOverview();case'profile':return profileView();case'discover':return discoverView();case'interests':return interestsView();case'introductions':return introductionView();case'profiles':return directoryView();case'reviews':return directoryView(true);case'add':return addProfileView();case'tasks':return tasksView();case'confirmations':return confirmationsView();case'appointments':return appointmentsView();case'membership':return membershipView();case'privacy':return privacyView();case'staff':return staffView();case'organisations':return organisationsView();case'partners':return partnersView();case'reports':return reportsView();case'content':return contentView();case'audit':return `${heading('Clear roles. Recorded actions.','Operational access is scoped; sensitive changes leave a record.')}${panel('Sensitive action history',auditBody())}<div class="demo-note">Demo roles: member owner, branch manager B01, church representative C01 and central reviewer. Reassignment removes the former organisation’s case access.</div>`;default:return memberOverview();}}
function render(){if(['member','branch','church','admin'].includes(page)){if(!user)return;$('#app').innerHTML=dashboard();}else $('#app').innerHTML=page==='home'?home():page==='about'?about():page==='specialties'?specialtyPage():loginPage();setup();}
function setup(){const ob=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');ob.unobserve(e.target);}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>ob.observe(el));setupJourney();setupCarousels();if(page==='home')loadMap();}
function scrollCarousel(track,direction){if(!track)return;const card=track.firstElementChild;const gap=parseFloat(getComputedStyle(track).gap)||24;track.scrollBy({left:direction*(card.getBoundingClientRect().width+gap),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
function setupCarousels(){document.querySelectorAll('[data-carousel-track]').forEach(track=>{const update=()=>{const atStart=track.scrollLeft<4,atEnd=track.scrollLeft+track.clientWidth>=track.scrollWidth-4;const prev=document.querySelector('[data-track="'+track.id+'"][data-direction="-1"]'),next=document.querySelector('[data-track="'+track.id+'"][data-direction="1"]');if(prev)prev.disabled=atStart;if(next)next.disabled=atEnd;const card=track.firstElementChild,gap=parseFloat(getComputedStyle(track).gap)||24;const index=card?Math.min(track.children.length,Math.round(track.scrollLeft/(card.getBoundingClientRect().width+gap))+1):1;const label=document.querySelector('[data-carousel-position="'+track.id+'"]');if(label)label.textContent=index+' / '+track.children.length;};track.addEventListener('scroll',update,{passive:true});track.addEventListener('keydown',e=>{if(e.target.closest('button,a,input,select,textarea'))return;if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();scrollCarousel(track,e.key==='ArrowRight'?1:-1);}if(['Home','End'].includes(e.key)){e.preventDefault();track.scrollTo({left:e.key==='Home'?0:track.scrollWidth,behavior:'auto'});}});if(typeof ResizeObserver!=='undefined')new ResizeObserver(update).observe(track);update();});}

function activateJourney(el,reveal=false){
 const track=el.closest('.journey-accordion');if(!track)return;
 const panels=[...track.querySelectorAll('button[data-journey]')],index=panels.indexOf(el);
 panels.forEach((panel,i)=>{const open=panel===el;panel.setAttribute('aria-expanded',String(open));panel.querySelector('.journey-detail').setAttribute('aria-hidden',String(!open));if(open)panel.setAttribute('aria-describedby','journey-description-'+i);else panel.removeAttribute('aria-describedby');});
 const label=document.querySelector('[data-carousel-position="'+track.id+'"]');if(label)label.textContent=(index+1)+' / '+panels.length;
 document.querySelectorAll('[data-action="journey-step"][data-track="'+track.id+'"]').forEach(button=>{button.disabled=Number(button.dataset.direction)<0?index===0:index===panels.length-1;});
 if(reveal&&matchMedia('(max-width: 979px)').matches){const style=getComputedStyle(track),closed=parseFloat(style.getPropertyValue('--journey-closed')),gap=parseFloat(style.gap);track.scrollTo({left:Math.max(0,index*(closed+gap)-3),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
}
function setupJourney(){
 const track=document.querySelector('.journey-accordion');if(!track)return;
 const panels=[...track.querySelectorAll('button[data-journey]')];
 panels.forEach(panel=>{panel.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse'&&matchMedia('(hover: hover)').matches)activateJourney(panel);});panel.addEventListener('focus',()=>activateJourney(panel,true));});
 track.addEventListener('keydown',e=>{const panel=e.target.closest('button[data-journey]');if(!panel)return;let index=panels.indexOf(panel);if(e.key==='ArrowRight')index=Math.min(panels.length-1,index+1);else if(e.key==='ArrowLeft')index=Math.max(0,index-1);else if(e.key==='Home')index=0;else if(e.key==='End')index=panels.length-1;else return;e.preventDefault();panels[index].focus({preventScroll:true});});
 activateJourney(panels.find(p=>p.getAttribute('aria-expanded')==='true')||panels[0]);
}
async function loadMap(){try{const r=await fetch('assets/india.svg');if(!r.ok)throw Error();$('#india-map').innerHTML=await r.text()+`<div class="map-caption">Five regional enquiry options · map: geoBoundaries / DataMeet, CC BY 2.5 IN</div>`;selectRegion('Karnataka');}catch{$('#india-map').innerHTML=`<div style="text-align:center"><div style="font-family:var(--serif);font-size:75px;color:#d5c4a0">India</div><p style="font-size:16px">Five regional enquiry options.<br>Select a state to begin.</p></div>`;}}
function selectRegion(s){document.querySelectorAll('[data-state]').forEach(el=>{if(el.classList.contains('state-chip'))el.setAttribute('aria-pressed',String(el.dataset.state===s));else{el.classList.toggle('selected',el.dataset.state===s);el.setAttribute('aria-pressed',String(el.dataset.state===s));}});if($('#regional-card'))$('#regional-card').innerHTML=regionContent(s);}
function openModal(content,wide=false){lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><button class="modal-close" data-action="close-modal" aria-label="Close dialog">${ic('close')}</button>${content}</section></div>`;$('#app').inert=true;document.body.style.overflow='hidden';$('.modal').focus();}
function closeModal(){ $('#modal-root').innerHTML='';$('#app').inert=false;document.body.style.overflow='';lastFocus?.focus();modalKind='';}
function info(title,text,cta=''){openModal(`<div class="eyebrow">A thoughtful process</div><h2 id="modal-title">${title}</h2><p>${text}</p>${cta}`);}
function showProfile(id,managed=false){const p=profileById(id);if(!p)return;if(managed&&!visibleProfiles(state,user).some(x=>x.id===id))return;const mine=user.role==='member'&&id===user.profileId;openModal(`<div class="modal-profile">${avatar(p)}<div><div class="eyebrow" style="font-size:12px;margin-bottom:12px">${p.id}</div><h2 id="modal-title">${esc(p.name)}</h2><p>${p.age} · ${esc(p.city)}, ${esc(p.state)}</p></div></div>${badge(p.status)}<div class="detail-grid"><div><small>Faith community</small><strong>${esc(p.denomination)}</strong></div><div><small>Profession</small><strong>${esc(p.career)}</strong></div><div><small>Language</small><strong>${esc(p.language||'English')}</strong></div><div><small>Original intake</small><strong>${esc(p.route)}</strong></div>${managed?`<div><small>Member consent</small><strong>${p.consent?'Recorded':'Awaiting member'}</strong></div><div><small>Required evidence</small><strong>${p.evidence?'Recorded in demo':'Outstanding'}</strong></div>`:''}</div><p>${esc(p.bio||'This member’s story is still being completed.')}</p>${managed?user.role==='admin'?`<form id="review-form" data-id="${p.id}">${selectField('decision','Review decision',['Approved','Changes requested','Suspended'],p.status==='Under review'?'Approved':p.status)}<div class="field"><label for="reason">Decision reason</label><textarea id="reason" name="reason" required maxlength="500" placeholder="Record the basis for your review…"></textarea></div><div class="form-error" role="alert"></div><button class="btn small" type="submit">Record review decision ${arrow()}</button></form>`:`<div class="inline-note">${ic('shield')}You can help with the draft. Only the member records consent; Covenant approves the profile.</div><button class="btn small" data-action="submit-profile" data-id="${p.id}">Submit to central review ${arrow()}</button>`:mine?'':`<div class="inline-note">${ic('shield')}Photos are illustrative. Contact details are kept private.</div><button class="btn" data-action="send-interest" data-id="${p.id}">Express interest ${arrow()}</button>`}`);}
function enquiry(type='general',region=''){modalKind='enquiry';openModal(`<div class="eyebrow">A conversation to begin</div><h2 id="modal-title">${type==='church'?'Begin through your church.':type==='branch'?'Ask about branch assistance.':type==='support'?'How can we help?':'Tell us where to begin.'}</h2><p>Leave a fictional enquiry to explore the showcase. No message is sent.</p><form id="enquiry-form" data-type="${type}"><div class="form-grid">${field('name','Your name')}${field('email','Email address','','email','required')}${type==='church'||type==='branch'?field('organisation',type==='church'?'Church name':'Organisation name'):''}${selectField('state','Preferred state',states,region||states[0])}<div class="field span-2"><label for="message">What would you like to know?</label><textarea id="message" name="message" required maxlength="800"></textarea></div></div><div class="form-error" role="alert"></div><button class="btn" type="submit">Save demo enquiry ${arrow()}</button></form>`);}
function registration(){wizardStep=0;wizardData={};showWizard();}
function showWizard(){openModal(`<div class="eyebrow">A first step, thoughtfully taken</div><h2 id="modal-title">Create your profile.</h2><div class="stepper">${[0,1,2].map(i=>`<span class="${i<=wizardStep?'done':''}"></span>`).join('')}</div><div class="steps-label">Step ${wizardStep+1} of 3 · ${['About you','Faith & location','Your permission'][wizardStep]}</div><form id="register-form"><div class="form-grid">${wizardStep===0?`${field('name','Your full name',wizardData.name||'')}${field('age','Your age',wizardData.age||'','number','required min="21" max="80"')}${selectField('gender','Gender',['Female','Male'],wizardData.gender)}${field('career','Profession',wizardData.career||'')}`:wizardStep===1?`${field('city','Your city',wizardData.city||'')}${selectField('state','State',states,wizardData.state)}${selectField('denomination','Faith community',['Protestant','Catholic','Orthodox','Other Christian'],wizardData.denomination)}${field('email','Your email',wizardData.email||'','email','required')}`:`<div class="span-2"><p style="margin-top:0">Your online draft begins one connected profile record. A member’s confirmed permission, required evidence and central approval determine publication.</p><label class="check"><input name="authority" type="checkbox" required><span>I authorise creation of this demonstration draft. I understand this does not publish a profile.</span></label><label class="check"><input name="fictional" type="checkbox" required><span>I have used fictional details for the showcase.</span></label><div class="demo-note">No payment, email, verification upload or live member registration takes place in this demo.</div></div>`}</div><div class="form-error" role="alert"></div><div class="actions"><button class="btn" type="submit">${wizardStep===2?'Create demo draft':'Continue'} ${arrow()}</button>${wizardStep>0?'<button class="text-link" type="button" data-action="wizard-back">Back</button>':''}</div></form>`);}
function filterItems(){const q=($('[data-search]')?.value||'').toLowerCase();const fs=[...document.querySelectorAll('[data-filter]')].map(s=>[s.dataset.filter,s.value]);let count=0;document.querySelectorAll('[data-searchable]').forEach(el=>{const show=el.dataset.searchable.includes(q)&&fs.every(([k,v])=>!v||el.dataset[k]===v);el.hidden=!show;if(show)count++;});if($('#filter-empty'))$('#filter-empty').hidden=count>0;}
function go(v){view=v;location.hash=v;render();$('#main')?.setAttribute('tabindex','-1');$('#main')?.focus({preventScroll:true});}
async function signIn(email,pw){if(config.backend==='php'){const r=await api('login',{email,password:pw});user=r.user;state=r.state;}else{user=Object.values(accounts).find(a=>a.email.toLowerCase()===email.toLowerCase());if(!user||pw!==password)throw Error('Use the email and password shown for this demo workspace.');if(user.org&&state.organisations.find(o=>o.id===user.org)?.status!=='Active')throw Error('This organisation’s access is suspended. Restore it from the admin demo.');sessionStorage.setItem('covenant-user',JSON.stringify(user));}location.href=user.role+'.html';}
document.addEventListener('click',async e=>{
 if(e.target.matches('.sidebar.open')&&e.clientX>e.target.getBoundingClientRect().right){e.target.classList.remove('open');return;}
 const role=e.target.closest('[data-role]');if(role){loginRole=role.dataset.role;render();return;}
 const journey=e.target.closest('button[data-journey]');if(journey){activateJourney(journey,true);return;}
 const region=e.target.closest('[data-state]');if(region){selectRegion(region.dataset.state);return;}
 const vt=e.target.closest('[data-view]');if(vt){closeModal();go(vt.dataset.view);return;}
 const tab=e.target.closest('[data-interest-tab]');if(tab){interestTab=tab.dataset.interestTab;render();return;}
 const b=e.target.closest('[data-action]');if(!b){if(e.target.classList.contains('modal-backdrop'))closeModal();return;}
 const a=b.dataset.action,id=b.dataset.id;
 try{
 switch(a){
 case'menu':$('.public-nav').classList.toggle('open');b.setAttribute('aria-expanded',String($('.public-nav').classList.contains('open')));break;
 case'sidebar':$('.sidebar').classList.toggle('open');b.setAttribute('aria-expanded',String($('.sidebar').classList.contains('open')));break;
 case'close-modal':closeModal();break;
 case'carousel-scroll':scrollCarousel(document.getElementById(b.dataset.track),Number(b.dataset.direction));break;
 case'journey-step':{const panels=[...document.getElementById(b.dataset.track).querySelectorAll('button[data-journey]')],index=panels.findIndex(p=>p.getAttribute('aria-expanded')==='true'),next=panels[Math.max(0,Math.min(panels.length-1,index+Number(b.dataset.direction)))];activateJourney(next,true);break;}
 case'register':registration();break;
 case'wizard-back':wizardStep=Math.max(0,wizardStep-1);showWizard();break;
 case'church-enquiry':enquiry('church');break;
 case'branch-enquiry':enquiry('branch');break;
 case'region-enquiry':enquiry('general',b.dataset.region||'Karnataka');break;
 case'enquiry':enquiry();break;
 case'support':enquiry('support');break;
 case'login':location.href='login.html';break;
 case'show-password':{const input=$('#password');input.type=input.type==='password'?'text':'password';b.textContent=input.type==='password'?'Show':'Hide';break;}
 case'recovery':info('Explore with demo credentials.',`This showcase uses fictional accounts. Select a workspace tab to fill its demo credentials.<br><br>Password: <strong>${password}</strong>`, '<button class="btn small" data-action="close-modal">Return to sign in</button>');break;
 case'logout':if(config.backend==='php')await api('logout');sessionStorage.removeItem('covenant-user');location.href='login.html';break;
 case'profile-detail':showProfile(id);break;
 case'managed-detail':showProfile(id,true);break;
 case'send-interest':await mutate('sendInterest',{id});closeModal();render();toast('Your interest is recorded. Contact details stay private.');break;
 case'respond-interest':await mutate('respondInterest',{id,response:b.dataset.response});render();toast(b.dataset.response==='Accepted'?'Mutual interest confirmed. A coordinator can now be assigned.':'Interest '+b.dataset.response.toLowerCase()+'.');break;
 case'privacy':{const value=b.getAttribute('aria-checked')!=='true';await mutate('privacy',{[b.dataset.key]:value});render();toast('Your visibility permission has been updated.');break;}
 case'submission-consent':await mutate('recordConsent',{id,value:b.getAttribute('aria-checked')!=='true'});render();toast('Your submission permission has been updated.');break;
 case'contact-consent':await mutate('contactConsent',{id,value:b.getAttribute('aria-checked')!=='true'});render();toast('Your family contact permission has been updated.');break;
 case'submit-profile':await mutate('submitProfile',{id});closeModal();render();toast('The profile is in the central review queue.');break;
 case'appointment':await mutate('appointment',{id,status:b.dataset.status});render();toast(b.dataset.status==='Confirmed'?'Appointment confirmed.':'A change request has been recorded.');break;
 case'task':await mutate('task',{id,done:b.dataset.done==='true'});render();toast('Task updated.');break;
 case'org-status':await mutate('orgStatus',{id});render();toast('Organisation access updated.');break;
 case'confirm-affiliation':openModal(`<div class="eyebrow">One considered check</div><h2 id="modal-title">Confirm church affiliation.</h2><p>Record the basis for confirming ${esc(profileById(id).name)}’s connection to your church.</p><form id="confirmation-form" data-id="${id}"><div class="field"><label for="basis">Confirmation basis</label><textarea id="basis" name="basis" required maxlength="500" placeholder="For example, membership record checked by the authorised representative…"></textarea></div><div class="inline-note">${ic('shield')}This does not approve the profile or create member consent.</div><div class="form-error" role="alert"></div><button class="btn small" type="submit">Record confirmation ${arrow()}</button></form>`);break;
 case'assign':openModal(`<div class="eyebrow">Central assignment</div><h2 id="modal-title">A person to guide the journey.</h2><p>Assign a coordinator to introduction ${esc(id)}. Reassignment removes the former organisation’s case access.</p><form id="assign-form" data-id="${id}">${selectField('coordinator','Assigned representative',['Pastor Samuel','Anna Mathew'])}<div class="form-error" role="alert"></div><button class="btn small" type="submit">Confirm assignment ${arrow()}</button></form>`);break;
 case'membership-grant':openModal(`<div class="eyebrow">Recorded annual entitlement</div><h2 id="modal-title">Grant a demo membership.</h2><p>The grant records an annual period for Rachel’s fictional member account. No payment takes place.</p><form id="grant-form"><div class="field"><label for="reason">Grant reason</label><textarea id="reason" name="reason" required maxlength="300"></textarea></div><div class="form-error" role="alert"></div><button class="btn small" type="submit">Record demo grant ${arrow()}</button></form>`);break;
 case'notifications':info('Your next steps.',user.role==='member'?`Review your interest responses, appointment requests and introduction permissions from the sidebar.`:`Your worklist shows outstanding profile tasks, review states and assigned introductions.`);break;
 case'preferences':if(user?.role==='member')openModal(`<div class="eyebrow">What matters to you</div><h2 id="modal-title">Your partner preferences.</h2><p>Use these as a starting point for a thoughtful conversation.</p><form id="preferences-form">${selectField('state','Preferred state',['Any state',...states],state.preferences.state)}${selectField('language','Preferred language',['English','Kannada','Malayalam','Tamil','Telugu'],state.preferences.language)}${selectField('relocation','Relocation',['Open to discussing','Prefer my current city','Open to relocating'],state.preferences.relocation)}<div class="form-error" role="alert"></div><button class="btn" type="submit">Save preferences ${arrow()}</button></form>`);else info('Make room for your faith.', 'Your faith community, church life and preferences help a thoughtful introduction begin.', '<button class="btn small" data-action="register">Create your profile '+arrow()+'</button>');break;
 case'family':info('Family, with your permission.','A family manager can help with profile details when you authorise them. Submission, expressing interest and family contact are separate permissions. Production onboarding will let you invite and remove specific family managers.');break;
 case'guided':info('A person for the next conversation.','When interest is mutual, central staff assign a pastor or representative. Your coordinator seeks separate permission from both participants before family contact, then helps with meetings and the agreed counselling process.');break;
 case'counselling':info('Prepare for the life ahead.','Premarital counselling makes room for conversations about expectations, responsibilities and shared life. Your coordinator helps arrange the agreed process. Private pastoral notes remain separate from shared progress.', '<button class="btn small" data-action="enquiry">Ask about the process '+arrow()+'</button>');break;
 case'privacy-policy':info('Privacy in this showcase.','This demonstration uses fictional profiles and generated illustrative photographs. Demo changes are stored in your browser, or on the PHP demo server when that version is used. Please enter fictional information only. No email is sent, and no identity documents or payments are collected. A complete privacy notice, retention policy and consent process must be approved before real-member use.','<button class="btn outline small" data-action="reset-demo">Reset browser demo data</button>');break;
 case'terms':info('About this demonstration.','This is a presentation of the proposed Covenant Matrimony experience. Profiles, organisations, appointments and review checks are illustrative. Annual pricing and benefits remain undecided. Regional state options are enquiries, and do not confirm offices or service availability. No successful marriage outcome is guaranteed.');break;
 case'reset-demo':if(config.backend!=='mock')throw Error('The PHP demo is reset by its server administrator.');state=seed();persist();closeModal();render();toast('Browser demo data reset.');break;
 case'export-report':{
  if(user?.role!=='admin')throw Error('Sign in to the admin workspace to download this report.');
  b.disabled=true;try{const bytes=await createAggregateReport(state);const blob=new Blob([bytes],{type:'application/pdf'});const u=URL.createObjectURL(blob),link=document.createElement('a');link.href=u;link.download='Covenant_Demo_Aggregate_Report_'+new Date().toISOString().slice(0,10)+'.pdf';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(u),4000);toast('Your PDF report has been downloaded.');}finally{b.disabled=false;}break;}

 }
 }catch(err){toast(err.message);}
});
document.addEventListener('submit',async e=>{
 const form=e.target;if(!form.id)return;e.preventDefault();const data=Object.fromEntries(new FormData(form));const error=$('.form-error',form);if(error)error.textContent='';const submit=$('[type=submit]',form);if(submit)submit.disabled=true;
 try{
 switch(form.id){
 case'login-form':await signIn(data.email,data.password);return;
 case'profile-form':await mutate('updateProfile',data);render();toast('Details saved. Submit the changes for central review.');break;
 case'add-form':await mutate('addProfile',{...data,authority:!!data.authority});go('profiles');toast('Draft saved. Member consent and evidence are the next steps.');break;
 case'review-form':await mutate('review',{id:form.dataset.id,status:data.decision,reason:data.reason});closeModal();render();toast('Central review decision recorded.');break;
 case'confirmation-form':await mutate('confirmation',{id:form.dataset.id,basis:data.basis});closeModal();render();toast('Church affiliation confirmation recorded.');break;
 case'assign-form':await mutate('assign',{id:form.dataset.id,coordinator:data.coordinator});closeModal();render();toast('Coordinator assigned. Access follows the new assignment.');break;
 case'grant-form':await mutate('membershipGrant',{reason:data.reason});closeModal();render();toast('Annual demo membership granted and recorded.');break;
 case'preferences-form':await mutate('preferences',data);closeModal();render();toast('Your preferences have been saved.');break;
 case'enquiry-form':{const payload={...data,type:form.dataset.type};if(config.backend==='php')await api('publicEnquiry',payload);else{state.enquiries.push({...payload,id:'E'+Date.now(),date:new Date().toISOString()});persist();}openModal(`<div class="success-icon">${ic('check')}</div><div class="eyebrow">A first conversation</div><h2 id="modal-title">Your demo enquiry is saved.</h2><p>The fictional enquiry is recorded in the showcase. No message has been sent.</p><button class="btn small" data-action="close-modal">Back to the journey ${arrow()}</button>`);break;}
 case'register-form':wizardData={...wizardData,...data};if(wizardStep<2){wizardStep++;showWizard();}else{if(!data.fictional)throw Error('Use fictional details for this showcase.');const payload={...wizardData,authority:true};if(config.backend==='php')await api('publicRegister',payload);else{state=apply(state,accounts.member,'addProfile',payload);persist();}openModal(`<div class="success-icon">${ic('check')}</div><div class="eyebrow">Your first step is recorded</div><h2 id="modal-title">A thoughtful beginning.</h2><p>Your fictional online draft is saved in the shared demo system. It remains unpublished until member consent, required evidence and central review are complete.</p><p style="font-size:15px">Explore the member dashboard using the pre-filled demo account. Your new draft appears in the admin demo’s review queue.</p><a class="btn" href="login.html">Explore the demo dashboard ${arrow()}</a>`);}break;
 }
 }catch(err){if(error)error.textContent=err.message;else toast(err.message);}finally{if(submit)submit.disabled=false;}
});
document.addEventListener('input',e=>{if(e.target.matches('[data-search]'))filterItems();});document.addEventListener('change',e=>{if(e.target.matches('[data-filter]'))filterItems();});
document.addEventListener('keydown',e=>{if(e.target.closest('.map-state.featured')&&['Enter',' '].includes(e.key)){e.preventDefault();selectRegion(e.target.dataset.state);}if(e.target.closest('[data-role]')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const rs=Object.keys(accounts);loginRole=rs[(rs.indexOf(loginRole)+(e.key==='ArrowRight'?1:3))%4];render();document.querySelector('[data-role="'+loginRole+'"]').focus();}if(e.key==='Escape'){if($('.modal'))closeModal();else{ $('.sidebar')?.classList.remove('open');$('.public-nav')?.classList.remove('open');}}if(e.key==='Tab'&&$('.modal')){const items=[...$('.modal').querySelectorAll('a,button,input,select,textarea,[tabindex="0"]')].filter(el=>!el.disabled);const first=items[0],last=items[items.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.modal'))){last?.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first?.focus();e.preventDefault();}}});
window.addEventListener('hashchange',()=>{if(user&&['member','branch','church','admin'].includes(page)){view=location.hash.slice(1)||'overview';render();}});
async function init(){state=loadState();if(config.backend==='php'){try{const r=await api('session');user=r.user;state=r.state||state;}catch(err){if(['member','branch','church','admin'].includes(page)){location.href='login.html';return;}}}else{try{user=JSON.parse(sessionStorage.getItem('covenant-user'));}catch{}if(user){const valid=accounts[user.role];user=valid?.email===user.email?valid:null;if(user?.org&&state.organisations.find(o=>o.id===user.org)?.status!=='Active')user=null;}}
 if(['member','branch','church','admin'].includes(page)){if(!user){location.href='login.html';return;}if(user.role!==page){location.href=user.role+'.html';return;}}
 render();}
if(!window.__COVENANT_TEST__)init();
export function renderForTest(role,nextView,customState=seed()){state=customState;user=accounts[role];view=nextView;return renderView();}
export {home,about,specialtyPage,loginPage};
